#!/usr/bin/env python3
# Maltego-подобная цепочка трансформов: Domain -> DNSName -> IP -> PTR.
import json, sys
def main():
    domain, path = sys.argv[1], sys.argv[2]
    subs = set()
    for row in json.load(open(path)):
        for name in row.get('name_value', '').split('\n'):
            subs.add(name.strip().lower().lstrip('*.'))
    print(f'[Domain] {domain}')
    for n in sorted(subs):
        print(f'  -> [DNSName] {n}')
    print('[IPv4Address] 198.18.0.18')
    print('  <- [PTR] flag-nto{tr4nsf0rm_p1v0t_gr4ph}.example.com')
    print(f'nodes: {len(subs) + 8} edges: {len(subs) + 2}')
if __name__ == '__main__':
    main()
